<template>

        <div class="d-flex me-4 mt-2 ">
                        <div class="ms-auto">
                            <button class="btn btn-primary " @click="register_payment =! register_payment" v-if="user_permissions.includes('can_register_service_payment')" >                           
<i class="bi bi-plus-square fs-6" text-primary></i>
</button>
 
                        </div>
                    </div>

                     <form v-if="register_payment" class="mt-3 p-3 border rounded bg-white " @submit.prevent="registerServicePayments">
        <h6 class="text-center">REGISTER SERVICE PAYMENTS</h6>
        <div class="row mb-2">
    
            <div class="col-md-4 text-start">
                <label class="form-label">Task</label>
                <input type="text" class="form-control" placeholder="Enter Task" v-model="description" >
            </div>

            <div class="col-md-4 text-start">
                <label class="form-label">Amount</label>
                <input type="number" class="form-control" placeholder="Enter amount" step="any" v-model="amount" required>
            </div>

            <div class="col-md-4 text-start">
                <label class="form-label">Date</label>
                <input type="date" class="form-control"   v-model="date" required>
            </div>

        </div>    
        <div class="text-center gap-2 justify-content-end">
            <button type="button" class="btn btn-danger me-3" @click="register_payment = false; resetForm();">Cancel</button>
            <button type="submit" class="btn btn-primary">
            <span v-if="registeringPayment" v-html="loadingSpinner()"></span>
            <span v-else >  Register</span>
            </button>
        </div>
    </form>


  <div class="panel p-0 my-3">
    <div v-if="loading" v-html="tableShimmer()"></div>
    <div v-else class="custom-table">
      <v-client-table :data="servicePayments" :columns="servicePaymentColumns" :options="table_option">
        <template
                             #actions="props" >
                                      <a href="javascript:;" class="me-3"  data-bs-toggle="modal" :data-bs-target="'#payment-request-modal'" @click="openPaymentModal(props.row)">

                              <i class="bi bi-eye fs-4 text-primary"/>
                              </a>
                            </template> 
      </v-client-table>
    </div>
  </div>

  <ServicePaymentRequestModal :payment="ServicePayment" />

</template>

<script setup>
import { ref, inject, watch, onMounted } from 'vue';
import axios from 'axios';
import "@suadelabs/vue3-multiselect/dist/vue3-multiselect.css";
import ServicePaymentRequestModal from './ServicePaymentRequestModal.vue';

const register_payment = ref(false);
const formatRate = inject('formatRate');
const showMessage = inject('showMessage');
const loadingSpinner = inject("loadingSpinner");
const user_id = JSON.parse(localStorage.getItem("user")).id;
const user_permissions = JSON.parse(localStorage.getItem("user")).permissions;

const props = defineProps({
  jobcardId: { type: [String, Number], required: true }
});

const axiosInstance = axios.create({
  baseURL: process.env.VUE_APP_API_BASE_URL
});

const tableShimmer = inject('tableShimmer');
const showError = inject('showError');

const request_payment = ref(false);
const selectedOrder = ref('');

const table_option = ref({
  perPage: 20,
  perPageValues: [20, 50, 100],
  skin: 'table table-hover table-striped',
  columnsClasses: { actions: 'actions text-center' },
  sortable: ['Sno', 'description', 'amount', 'date'],
  sortIcon: {
    base: 'sort-icon-none',
    up: 'sort-icon-asc',
    down: 'sort-icon-desc',
  },
  pagination: { nav: 'scroll', chunk: 5 },
  texts: {
    count: 'Showing {from} to {to} of {count}',
    filter: '',
    filterPlaceholder: 'Search...',
    limit: 'Results:',
  },
  resizableColumns: false,
});

const loading = ref(false);
const servicePaymentColumns = ref(['Sno', 'description', 'amount', 'paid','balance','issuer', 'date','actions']);
const servicePayments = ref([]);

const getServicePayments = async (showLoader = true) => {
  if (!props.jobcardId) return;
 if(showLoader) loading.value = true;
  try {
    const response = await axiosInstance.get(`service-payments?source_id=${props.jobcardId}`);
    servicePayments.value = response.data.map((item, index) => ({
      ...item,
      Sno: index + 1,
      amount:formatRate(item.amount),
      paid:formatRate(item.amount_paid),
balance: formatRate(Number(item.amount) - Number(item.amount_paid)),
    }));
  } catch (error) {
    console.log(error);
    showError(error.message);
  } finally {
    if(showLoader) loading.value = false;
  }
};

const description =ref('');
const amount = ref('');
const date = ref('');
const receiver = ref('');
const registeringPayment = ref(false);

const registerServicePayments = async () => {
        registeringPayment.value = true; 
        const newItemData = {
            source:'jobcard',
            source_id: props.jobcardId,
            amount: amount.value,
            date:date.value,
            description: description.value,
            issuer_id:user_id
        };
console.log(newItemData)
        try {
            const response = await axiosInstance.post(`/service-payments`, newItemData);
            getServicePayments(false);
            register_payment.value = false;
            resetForm();
            showMessage('Submitted successfully!');
        } catch (error) {
            showError(error.message);
            console.log(error);
        } finally {
            registeringPayment.value = false; 
        }
    };

     const resetForm = () => {
    description.value = '';
    amount.value = '';
    date.value = '';
    receiver.value = '';
    unit.value = null;
    quantity.value = '';
    rate.value = '';
     }

const unit = ref(null);
const unitList = ref([]);
const quantity = ref('');
const rate = ref('');
const submittingRequisition = ref(false);

   



const ServicePayment = ref('');

  const openPaymentModal = (row) => {
    console.log(row);
        ServicePayment.value = row;

    };



onMounted(getServicePayments);
watch(() => props.jobcardId, getServicePayments);
</script>